/* Banco DGAC · sección «Air conditioning and pneumatic» · 85 preguntas, una por línea.
   Id de cada pregunta en la app: "dgac_bank:" + hash del enunciado (tools/buscar.js lo calcula). */
window.DGAC_SECTIONS=window.DGAC_SECTIONS||{};
window.DGAC_SECTIONS["Air conditioning and pneumatic"]=[
{"q":"AFT CARGO INDICATIONS MAY BE FOUND ON WHICH ECAM PAGE (S)?","options":["ONLY THE ECAM CRUISE PAGE.","ONLY THE BLEED PAGE.","ONLY THE CAB PRESS PAGE.","THE ECAM CRUISE PAGE AND THE COND PAGE."],"correct":3,"expl":"Las indicaciones de la bodega de carga trasera se presentan tanto en la página ECAM CRUISE como en la página COND, no exclusivamente en una sola de ellas.","cite":"Indicaciones de bodega de carga trasera: presentes en ECAM CRUISE y en la página COND.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"AFT CARGO VENTILATION IS CONTROLLED BY:","options":["THE AFT CARGO ROTARY SELECTOR KNOB.","THE CARGO VENTILATION CONTROLLER.","THE ZONE CONTROLLER AND THE SDCU.","THE CARGO VENTILATION CONTROLLER & THE AFT CARGO ROTARY SELECTOR KNOB."],"correct":1,"expl":"La ventilación de la bodega de carga trasera está controlada por el Cargo Ventilation Controller, no directamente por la perilla rotativa ni por el conjunto zone controller/SDCU.","cite":"Control de la ventilación de bodega trasera: Cargo Ventilation Controller.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"AN AMBER FAULT LIGHT IN THE HOT AIR P/B INDICATES:","options":["VALVE POSITION DISAGREES WITH COMMANDED POSITION.","A DUCT OVERHEAT IS DETECTED.","EITHER A OR B."],"correct":2,"expl":"La luz FAULT ámbar del hot air pb puede deberse tanto a que la posición de la válvula no coincide con la comandada, como a la detección de un sobrecalentamiento de ducto; cualquiera de las dos causas es válida.","cite":"FAULT del hot air pb: discrepancia de posición de válvula o duct overheat detectado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"APU BLEED AIR, WHEN SELECTED.","options":["HAS PRIORITY OVER ENGINE BLEED AIR.","WILL SUPPLY BLEED AIR ONLY IF THE ENG BLEED PB´S ARE SELECTED OFF.","WILL SUPPLY AIR ONLY IF THE X BLEED SELECTOR IS SELECTED OPEN.","DOES NOT HAVE PRIORITY OVER ENGINE BLEED AIR."],"correct":0,"expl":"El bleed del APU tiene prioridad sobre el bleed de motor cuando está seleccionado, de forma análoga (pero independiente) a la lógica de prioridad eléctrica del sistema.","cite":"El bleed del APU tiene prioridad sobre el bleed de motor cuando está seleccionado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"AT WHAT CABIN ALTITUDE DO YOU GET AN ECAM WARNING?","options":["8,800 FEET.","9,000 FEET.","9,550 FEET.","14,000 FEET."],"correct":2,"expl":"El aviso ECAM de altitud de cabina se activa a 9,550 ft, un umbral distinto y más bajo que el de encendido de letreros (11,300 ft) o el de caída de máscaras (14,000 ft).","cite":"Umbral del warning ECAM de altitud de cabina: 9,550 ft.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"AVIONICS VENTILATION SYSTEM INDICATIONS MAY BE FOUND ON WHICH ECAM PAGE(S)?","options":["ONLY THE CAB PRESS PAGE.","THE INFLIGHT ECAM CRUISE PAGE.","THE INFLIGHT ECAM CRUISE PAGE AND THE CAB PRESS PAGES.","ONLY THE BLEED PAGE."],"correct":0,"expl":"Las indicaciones del sistema de ventilación de aviónica se muestran únicamente en la página CAB PRESS, a diferencia de la bodega de carga trasera, que también aparece en la página CRUISE.","cite":"Indicaciones de ventilación de aviónica: únicamente en la página CAB PRESS.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"BLEED AIR NORMALLY COMES FROM THE ________ OF THE ENGINE.","options":["HIGH PRESSURE STAGE.","INTERMEDIATE STAGE.","LOW PRESSURE STAGE."],"correct":1,"expl":"El aire sangrado proviene normalmente de la etapa intermedia (intermediate stage) del motor; la etapa de alta presión se usa como respaldo cuando la presión intermedia no es suficiente, por ejemplo en ralentí.","cite":"Fuente normal del bleed air: etapa intermedia del compresor del motor.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"BLEED AIR SUPPLIED FROM THE APU (APU BLEED VALVE OPEN), THE PACK FLOW IS AUTOMATICALLY SELECTED:","options":["HIGH.","NORMAL.","LOW.","ECON. FLOW."],"correct":0,"expl":"Cuando el bleed proviene del APU, el flujo de los packs se selecciona automáticamente en HIGH, la misma lógica que aplica si un pack falla.","cite":"Con bleed del APU en uso, el flujo de los packs pasa automáticamente a HIGH.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"BOTH PRESSURIZATION AUTO CONTROLLERS ARE SET BY THE ACTIVE FLIGHT PLAN LOADED IN THE MCDU. THE QNH ENTRY ON THE MCDU APPROACH PERFORMANCE PAGE REFINES THE DEPRESSURIZATION SCHEDULE FOR THE LANDING.","options":["TRUE.","FALSE."],"correct":0,"expl":"Verdadero: los controladores de presurización usan el plan de vuelo activo, y el QNH ingresado en la página de performance de aproximación afina el programa de despresurización para el aterrizaje.","cite":"Los controladores de presurización usan el plan de vuelo y se refinan con el QNH de la página de aproximación del MCDU.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"DURING GROUND FUNCTION OPERATION, THE OUTFLOW VALVE IS:","options":["FULLY OPEN.","FULLY CLOSED.","POSITIONED ACCORDING TO FMGS DEMANDS."],"correct":0,"expl":"En tierra, la válvula de outflow permanece completamente abierta, ya que no hay necesidad de mantener presión diferencial hasta iniciar el despegue.","cite":"En tierra, la válvula de outflow está completamente abierta.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"DURING NORMAL FLIGHT, THE AVIONICS VENTILATION SYSTEM CONTROLS THE TEMPERATURE OF THE COOLING AIR BY:","options":["ADDING AIR CONDITIONED AIR TO THE FLOW.","EXTRACTING AIR OVER BOARD.","ADDING A AVIONICS BAY AIR.","PASSING AIR THROUGH A SKIN HEAT EXCHANGER."],"correct":3,"expl":"En vuelo normal (circuito cerrado), la temperatura del aire de enfriamiento de aviónica se controla haciéndolo pasar por un intercambiador de calor con el fuselaje (skin heat exchanger), no agregando aire acondicionado ni extrayendo al exterior.","cite":"Control de temperatura del aire de aviónica en circuito cerrado: intercambiador de calor con el fuselaje.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"DURING THE EXTERIOR PREFLIGHT ON A WARM DAY, IN WHAT POSITION WOULD YOU EXPECT TO FIND THE AVIONICS VENTILATION SYSTEM INLET AND EXTRACT VALVES TO BE IN?","options":["OPEN.","INTERMEDIATE.","CLOSED.","FIRE."],"correct":0,"expl":"En tierra y con temperatura cálida, es esperable encontrar las válvulas de entrada y extracción del sistema de ventilación de aviónica abiertas, ya que en esa condición conviene el circuito abierto en vez del intercambiador de calor usado en vuelo.","cite":"En tierra con clima cálido, las válvulas de ventilación de aviónica se encuentran normalmente abiertas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"ENGINE BLEED AIR TEMPERATURE IS CONTROLLED BY:","options":["ENGINE OIL.","A PRE-COOLER THAT USES FAN AIR.","CONDITIONED AIR FROM THE MIXING UNIT."],"correct":1,"expl":"La temperatura del aire sangrado del motor se controla mediante un precooler que usa aire de fan, no mediante el aceite del motor ni con aire condicionado de la mixing unit.","cite":"Control de temperatura del bleed air: precooler alimentado con aire de fan.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"ENGINE FLOW DEMAND, WHEN THE HEATING OR COOLING DEMAND IN ONE ZONE CANNOT BE SATISFIED.","options":["THE MINIMUM IDLE MUST BE INCREASED MANUALLY.","THE MINIMUM IDLE IS INCREASED AUTOMATICALLY.","IN ANY CASE, FLIGHT IDLE IS SUFFICIENT.","THE APU MUST BE USED TO SUPPLY ADDITIONAL AIR."],"correct":2,"expl":"El sistema está diseñado de forma que el ralentí de vuelo (flight idle) es suficiente para satisfacer la demanda de una zona, sin necesitar un incremento manual del idle ni depender del APU como fuente adicional.","cite":"El flight idle es suficiente para cubrir la demanda de climatización de cualquier zona.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOT AIR FAUL LIGHT ILLUMINATES ON THE AIR CONDITIONING PANEL.","options":["THE HOT AIR PRESS. REG. VALVE OPENS AND THE TRIM AIR VALVES CLOSE.","THE HOT AIR PRESS. REG. VALVE CLOSES AND THE TRIM AIR VALVES OPEN.","THE HOT AIR PRESS. REG. VALVE CLOSES AND THE TRIM AIR VALVES CLOSE.","THE HOT AIR PRESS. REG. VALVE OPENS AND THE TRIM AIR VALVES OPEN."],"correct":2,"expl":"Ante un fault de hot air, tanto la válvula reguladora de presión de aire caliente como las válvulas de trim air se cierran, protegiendo al sistema de un sobrecalentamiento, no que una abra mientras la otra cierra.","cite":"Ante FAULT de hot air: cierre conjunto de la válvula reguladora y de las válvulas de trim air.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOT AIR PRESS. REG. VALVE FAILED OPEN.","options":["OPTIMIZED REGULATION IS LOST.","THE TEMPERATURE STAYS AT THE VALUE SELECTED.","NO EFFECT.","CABIN TEMPERATURE WILL BE CONTROLLED AT THE UPPER LIMIT 30 DEG. C."],"correct":2,"expl":"Si esta válvula falla en posición abierta, no hay efecto operacional relevante, ya que esa es esencialmente su posición normal de trabajo; la regulación fina de temperatura sigue a cargo de las válvulas de trim air.","cite":"Falla en posición abierta de la válvula reguladora de hot air: sin efecto operacional relevante.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOT AIR PRESSURE REGULATING VALVE:","options":["REGULATES THE PRESSURE OF HOT AIR TAPPED UPSTREAM OF THE PACKS.","IS SPRING LOADED OPEN IN THE ABSENCE OF AIR.","OPENS AUTOMATICALLY IN CASE OF DUCT OVERHEAT.","OPENS AUTOMATICALLY IF THE CABIN TRIM AIR VALVE FAILS."],"correct":0,"expl":"Esta válvula regula la presión del aire caliente tomado aguas arriba de los packs, el aire que luego alimenta el sistema de trim air para el ajuste fino de temperatura por zona.","cite":"La válvula reguladora de hot air regula presión de aire tomado antes de los packs, para alimentar el sistema de trim air.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOW CAN YOU CHANGE PRESSURIZATION CONTROLLERS DURING FLIGHT?","options":["CYCLE THE LDG ELEV AUTO KNOB OUT OF THE AUTO POSITION THEN BACK TO AUTO.","CYCLE THE CABIN PRESS MODE SEL PUSHBUTTON TO THE MAN POSITION THEN BACK TO AUTO.","CYCLE THE CABIN PRESSURIZATION MAN V/S CTL SWITCH."],"correct":1,"expl":"Para forzar el cambio de controlador de presurización en vuelo, se cicla el pushbutton CABIN PRESS MODE SEL a MAN y luego de vuelta a AUTO, no ciclando el selector de elevación de aterrizaje ni el switch manual de V/S.","cite":"Cambio de controlador de presurización en vuelo: ciclar CABIN PRESS MODE SEL de AUTO a MAN y de vuelta a AUTO.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOW MANY OUTFLOW VALVES ARE THERE?","options":["ONE VALVE WITH ONE DOOR.","ONE VALVE WITH TWO DOORS.","TWO VALVES WITH ONLY ONE DOOR VISIBLE.","TWO VALVES (ONE MAIN + ONE BACK-UP) WITH ONLY TWO DOORS VISIBLE."],"correct":1,"expl":"Existe una sola válvula de outflow, compuesta por dos puertas (doors), no dos válvulas separadas.","cite":"El sistema tiene una única válvula de outflow con dos puertas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOW MANY TEMPERATURE SELECTORS ARE THERE ON THE A-320? HOW MANY TEMPERATURE ZONES ARE THERE?","options":["THREE ROTARY TEMPERATURE SELECTORS AND ONE ZONE.","THREE ROTARY TEMPRERATURE SELECTORS, ONE EACH FOR THE COCKPIT ZONE, THE FORWARD CABIN ZONE, AND THE AFT CABIN ZONE.","TWO ROTARY TEMPERATURE SELECTORS, ONE FOR THE COCKPIT AND FIRST CLASS ZONE AND ONE FOR THE AFT CABIN ZONE.","FOUR ROTARY TEMPERATURE SELECTORS AND FOUR ZONES."],"correct":1,"expl":"El A320 tiene tres selectores rotativos de temperatura, uno para cada una de las tres zonas: cockpit, cabina delantera, y cabina trasera.","cite":"Arquitectura de zonas de temperatura A320: tres selectores, uno por zona (cockpit, cabina delantera, cabina trasera).","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"HOW MANY TRIM AIR VALVES ARE THERE?","options":["ONE TRIM AIR VALVE.","THREE: ONE EACH FOR THE COCKPIT ZONE, THE FORWARD CABIN ZONE, AND THE AFT CABIN ZONE.","TWO: ONE FOR THE COCKPIT AND FIRST CLASS ZONE, AND ONE FOR THE CABIN ZONE.","FOUR: ONE EACH FOR THE COCKPIT ZONE, THE FIRST CLASS ZONE, AND TWO FOR THE AFT ZONE."],"correct":1,"expl":"Hay tres válvulas de trim air, una para cada una de las tres zonas de temperatura del avión.","cite":"Cantidad de válvulas de trim air: tres, una por zona.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IF A BMC FAILS:","options":["THE REMAINING BMC WILL AUTOMATICALLY ASSUME MOST OF THE FAILED BMC´S FUNCTIONS.","ALL SYSTEM ASOCIATED WITH THE FAILED BMC ALSO FAIL.","THE ASSOCIATED BLEED VALVES CLOSE.","NONE OF THE ABOVE."],"correct":0,"expl":"Ante la falla de un BMC, el BMC restante asume automáticamente la mayoría de las funciones del que falló, sin que fallen todos los sistemas asociados ni se cierren automáticamente las válvulas de bleed.","cite":"Ante falla de un BMC, el BMC restante asume automáticamente la mayoría de sus funciones.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IF BLEED AIR IS BEING SUPPLIED BY THE APU OR IF ONE PACK FAILS, PACK FLOW WILL GO TO WHAT RATE?","options":["LOW.","MEDIUM.","HIGH."],"correct":2,"expl":"Con bleed del APU en uso o ante la falla de un pack, el flujo del/de los pack(s) restante(s) pasa automáticamente a HIGH.","cite":"Flujo de pack automático a HIGH: con bleed del APU o ante falla de un pack.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IF YOU SELECT A POSITION OTHER THAN THE AUTO DETENT ON THE LDG ELEV AUTO SELECTOR, HOW CAN YOU SEE TE ACTUAL LANDING ELEVATION VALUE?","options":["ON THE ECAM CRUISE.","ON THE PRESS PAGE.","ON THE ECAM CRUISE OR THE PRESS PAGE."],"correct":2,"expl":"El valor de elevación de aterrizaje seleccionado manualmente puede verificarse tanto en la página ECAM CRUISE como en la página PRESS.","cite":"Verificación de la elevación de aterrizaje seleccionada manualmente: páginas ECAM CRUISE y PRESS.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IN FLIGHT IF THE AIR PRESSURE IS INSUFFICIENT EVEN WITH THE HP VALVE OPEN:","options":["THE ENGINE SPOOLS UP AUTOMATICALLY. Spools up: incremento en thrust","ENGINE POWER HAS TO BE INCREASED BY THE PILOT.","PUSH THE HIGH PRESSURE P/B ON THE OVERHEAD PANEL."],"correct":0,"expl":"Si la presión de aire sigue siendo insuficiente incluso con la válvula de alta presión abierta, el motor incrementa automáticamente su régimen (spool up) para restablecer la presión requerida, sin que el piloto deba aumentar manualmente la potencia.","cite":"Ante presión de aire insuficiente con HP valve abierta, el motor incrementa automáticamente su régimen.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IN NORMAL FLIGHT IN CLOSED CIRCUIT CONFIGURATION, THE AVIONICS VENTILATION SYSTEM CONTROLS THE TEMPERATURE OF THE COOLING AIR BY:","options":["ADDING AIR CONDITIONED AIR TO THE FLOW.","EXTRACTING AIR OVERBOARD.","ADDING AVIONICS BAY AIR.","PASSING AIR THROUGH A SKIN HEAT EXCHANGER."],"correct":3,"expl":"En circuito cerrado, la temperatura del aire de enfriamiento de aviónica se controla haciéndolo pasar por un intercambiador de calor con el fuselaje, no agregando aire condicionado ni extrayendo al exterior.","cite":"Control de temperatura en circuito cerrado: intercambiador de calor con el fuselaje.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"IT IS PERMISSIBLE TO USE SIMULTANEOUSLY PACKS AND LP GROUND UNIT DURING LONG STOPS IN A HOT AIRFIELD.","options":["YES.","NO."],"correct":1,"expl":"No: no está permitido usar simultáneamente los packs del avión y una unidad de aire de baja presión en tierra durante escalas largas en un aeródromo caluroso.","cite":"No se permite el uso simultáneo de los packs y una unidad de aire de tierra de baja presión.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PACK CONTROLLER, PRIMARY AND SECONDARY CHANNEL FAILURE.","options":["PACK OUTLET TEMPERATURE IS CONTROLLED TO BETWEEN 5 AND 30 DEG. C BY THE ANTI-ICE VALVE.","THE PACK IS CLOSED.","THE PACKS DELIVER A FIXED TEMPERATURE OF 20 DEG. C."],"correct":0,"expl":"Si fallan ambos canales del pack controller, la válvula de anti-hielo asume un control básico de respaldo, manteniendo la temperatura de salida del pack entre 5 y 30°C, en vez de perder el pack por completo o fijar una temperatura única.","cite":"Con ambos canales del pack controller fallados: control de respaldo vía válvula de anti-hielo, entre 5 y 30°C.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PACK CONTROLLER, PRIMARY CHANNEL FAILURE.","options":["THE SECONDARY COMPUTER OPERATES AS A BACKUP MODE AND REGULATION IS NOT OPTIMIZED.","THE SECONDARY COMPUTER TAKES OVER (ALL FUNCTIONS AS NORMAL)","PACK IS LOST.","PACK OUTLET TEMPERATURE IS CONTROLLED AT 15 DEG.C"],"correct":0,"expl":"Ante la falla del canal primario, el canal secundario opera como respaldo, pero la regulación deja de estar optimizada respecto de la operación normal con ambos canales.","cite":"Falla del canal primario del pack controller: el secundario opera en modo de respaldo no optimizado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PACK CONTROLLER, SECONDARY CHANNEL FAILURE.","options":["NO EFFECT ON PACK REGULATION BACKUP MODE IS LOST.","PACK IS LOST.","NO EFFECT (ALL MODES STILL AVAILABLE).","PACK OUTLET TEMPERATURE IS CONTROLLED AT 15 DEG. C."],"correct":0,"expl":"Si falla el canal secundario (de respaldo) mientras el primario sigue funcionando, no hay efecto inmediato en la regulación, pero se pierde la capacidad de respaldo ante una eventual falla posterior del canal primario.","cite":"Falla del canal secundario del pack controller: sin efecto inmediato, pero se pierde la capacidad de respaldo.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PACK FLOW CONTROL VALVE:","options":["IS PNEUMATICALLY OPERATED AND ELECTRICALLY CONTROLLED.","ELECTRICALLY OPERATED AND PNEUMATICALLY CONTROLLED.","OPENS AUTOMATICALLY DURING ENGINE STARTING.","IS SPRING LOADED TO OPEN."],"correct":0,"expl":"La válvula de control de flujo de pack es de actuación neumática y control eléctrico, el mismo patrón de diseño usado en otras válvulas del sistema neumático del A320.","cite":"Válvula de control de flujo de pack: actuación neumática, control eléctrico.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PLACING THE AVIONICS VENTILATION SYSTEM IN THE SMOKE CONFIGURATION:","options":["OPENS THE #1 GLC.","OPENS THE CARGO UNDER-FLOOR VALVE.","OPENS THE #2 GLC.","DE-ENERGIZES THE BLOWER FAN, EXTRACT FAN RUNS, AND OPENS THE AIR CONDITIONING EXTRACT VALVES."],"correct":3,"expl":"La configuración de humo desenergiza el blower fan, mantiene funcionando el extract fan, y abre las válvulas de extracción del sistema de aire acondicionado, buscando expulsar el humo en vez de recircularlo.","cite":"Configuración de humo del sistema de ventilación de aviónica: blower apagado, extract fan activo, válvulas de extracción abiertas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PLACING THE BLOWER PUSH BUTTON TO OVERRIDE:","options":["INSURES THE BLOWER FAN WILL CONTINUE TO RUN.","PLACES THE AVIONICS VENTILATION SYSTEM IN THE OPEN CONFIGURATION.","DE-ENERGIZES THE BLOWER FAN.","PLACES THE AVIONICS VENTILATION SYSTEM IN THE CLOSED CONFIGURATION."],"correct":2,"expl":"El override del blower desenergiza específicamente ese ventilador, no asegura que siga funcionando ni cambia la configuración general del sistema por sí solo.","cite":"El override del blower pushbutton desenergiza el ventilador blower.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PLACING THE EXTRACT PUSH BUTTON TO OVERRIDE:","options":["DE-ENERGIZES THE EXTRACT FAN.","PLACES THE AVIONICS VENTILATION SYSTEM IN THE CLOSED CONFIGURATION.","INSURES THE EXTRACT FAN WILL CONTINUE TO BE ENERGIZED.","PLACES THE AVIONICS VENTILATION SYSTEM IN THE OPEN CONFIGURATION."],"correct":2,"expl":"El override del extract asegura que ese ventilador permanezca energizado, lo opuesto al override del blower.","cite":"El override del extract pushbutton asegura que el ventilador de extracción permanezca energizado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PRESSURIZATION CONTROLLERS RECEIVE INPUTS FROM:","options":["LGCIU, ADIRU, FMGS, AND EIU.","LGCIU/'S AND THE MCDU.","LGCIU/'S AND PITOT STATIC SOURCES.","MCDU AND LGCIU/'S."],"correct":0,"expl":"Los controladores de presurización reciben datos de LGCIU (posición de tren), ADIRU (datos de aire), FMGS (plan de vuelo) y EIU, una combinación más amplia que solo LGCIU y MCDU.","cite":"Entradas de los controladores de presurización: LGCIU, ADIRU, FMGS y EIU.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PRESSURIZATION INDICATIONS ARE FOUND WHICH ECAM PAGE(S)?","options":["ONLY ON THE CAB PRESS PAGE.","BLEED PAGE.","THE INFLIGHT ECAM CRUISE PAGE AND THE CAB PRESS PAGE.","BOTH A AND B."],"correct":3,"expl":"Las indicaciones de presurización se presentan en más de una página ECAM, incluyendo la página CAB PRESS entre ellas.","cite":"Las indicaciones de presurización se distribuyen en varias páginas del ECAM, incluida CAB PRESS.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"PRESSURIZATION IS NORMALLY AUTOMATIC. CAN YOU INTERFERE WITH IT?","options":["YES, CABIN PRESS MODE SEL TO OVERRIDE AND MAN V/S CTL TOGGLE SWITCH.","YES, MANUALLY SET LANDING ELEVATION USING THE LND ELEV AUTO SELECTOR.","BOTH ARE CORRECT."],"correct":0,"expl":"Sí: la tripulación puede intervenir manualmente seleccionando CABIN PRESS MODE SEL a MAN y usando el switch toggle de control manual de V/S.","cite":"Intervención manual de la presurización: CABIN PRESS MODE SEL en MAN más el switch de control manual de V/S.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"RECIRCULATION FANS IN THE AIR CONDITIONING SYSTEM DIRECT FILTERED CABIN AIR TO WHICH AREA?","options":["THE PNEUMATIC DUCK, UPSTREAM OF THE PACKS.","THE AVIONICS COMPARTMENT.","THE MIXING UNIT."],"correct":2,"expl":"Los ventiladores de recirculación dirigen el aire filtrado de cabina hacia la mixing unit, donde se combina con el aire fresco proveniente de los packs.","cite":"El aire de recirculación se dirige a la mixing unit.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"TEMPERATURE REGULATION FOR THE A-320 IS CONTROLLED BY:","options":["ONE ZONE CONTROLLER AND TWO PACK CONTROLLERS.","TWO PACK CONTROLLER AND THE BMC'S.","THE BMC'S."],"correct":0,"expl":"La regulación de temperatura combina un único Zone Controller (para las tres zonas) con dos Pack Controllers (uno por pack), no solo los BMC ni solo los pack controllers.","cite":"Regulación de temperatura A320: un Zone Controller más dos Pack Controllers.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE AUTO POSITION OF THE X BLEED SELECTOR OPENS THE CROSSBLEED IF:","options":["AN ENGINE BLEED VALVE IS OPEN.","THE APU BLEED VALVE IS OPEN.","WHEN ENGINE START IS SELECTED."],"correct":1,"expl":"En posición AUTO, el crossbleed se abre automáticamente cuando la válvula de bleed del APU está abierta, permitiendo distribuir el aire del APU hacia ambos lados del avión.","cite":"Apertura automática del crossbleed en AUTO: cuando la válvula de bleed del APU está abierta.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE CREW MAY DIRECTLY CONTROL THE FOLLOWING BLEED VALVES:","options":["ENGINE, ENGINE HIGH PRESSURE, APU.","ENGINE, INTERMEDIATE PRESSURE, APU.","ENGINE, APU, CROSSBLEED."],"correct":2,"expl":"La tripulación controla directamente las válvulas de bleed de motor, del APU, y la de crossbleed; las válvulas internas de alta/intermedia presión se gestionan automáticamente.","cite":"Válvulas de bleed controladas directamente por la tripulación: motor, APU y crossbleed.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE HOT AIR VALVE PUSH BUTTON CONTROLS:","options":["THE TRIM AIR VALVE.","THE HOT AIR MANIFOLD.","THE ENGINE BLEED VALVES.","THE PACK FLOW CONTROL VALVES."],"correct":1,"expl":"El pushbutton de hot air controla el manifold de aire caliente en general, no directamente una válvula individual de trim air, las válvulas de bleed de motor, ni las de flujo de pack.","cite":"El hot air pushbutton controla el manifold de aire caliente.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE LAVATORY/GALLEY EXTRACT FAN OPERATES:","options":["ONLY ON THE GROUND.","ONLY IN FLIGHT.","CONTINUOUSLY WHEN ELECTRICAL POWER IS AVAILABLE."],"correct":2,"expl":"El extractor de lavatorios/galley funciona de forma continua siempre que haya energía eléctrica disponible, no solo en tierra ni solo en vuelo.","cite":"El extract fan de lavatorios/galley opera continuamente con energía eléctrica disponible.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE OUTFLOW VALVE IS POWERED BY:","options":["ONE OF TWO ELECTRIC MOTORS.","ONE OF THREE ELECTRIC MOTORS.","THREE MECHANICALLY LINKED ELECTRIC MOTORS."],"correct":1,"expl":"La válvula de outflow está accionada por uno de tres motores eléctricos disponibles, dos de operación automática y uno manual de respaldo.","cite":"La válvula de outflow cuenta con tres motores eléctricos disponibles.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE PURPOSE OF THE SAFETY VALVE IS TO AVOID:","options":["EXCESSIVE POSITIVE PRESSURE DIFFERENTIAL.","EXCESSIVE NEGATIVE DIFFERENTIAL.","BOTH ARE CORRECT."],"correct":2,"expl":"La válvula de seguridad protege tanto contra una diferencial de presión positiva excesiva como contra una diferencial negativa excesiva; ambas condiciones están cubiertas.","cite":"La válvula de seguridad protege contra diferencial de presión excesiva, tanto positiva como negativa.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE RAM AIR SWITCH SHOULD BE USED:","options":["AT ANY TIME.","ONLY WHEN DIFFERENTIAL PRESSURE IS LESS THAN 1 PSI.","WHEN DIFFERENTIAL PRESSURE IS MORE THAN 1 PSI.","ONLY AFTER OUTFLOW VALVE IS FULLY OPENED."],"correct":1,"expl":"El switch de ram air solo debe usarse cuando la presión diferencial de cabina es menor a 1 PSI, una condición de seguridad para evitar abrirlo con presurización significativa aún presente.","cite":"Uso del ram air switch: solo con diferencial de presión de cabina menor a 1 PSI.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE RAM AIR VALVE:","options":["SHOULD BE OPENED FOR INCREASED VENTILATION WHILE ON THE GROUND.","WILL OPEN AUTOMATICALLY AFTER ENGINE START.","SHOULD BE OPENED FOR INCREASED VENTILATION WHILE IN FLIGHT.","MUST BE MANUALLY ACTIVATED."],"correct":3,"expl":"La válvula de ram air debe activarse manualmente por la tripulación; no se abre automáticamente ni al arrancar motores ni para ventilación rutinaria en tierra o en vuelo.","cite":"La válvula de ram air requiere activación manual de la tripulación.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE SAFETY VALVES ARE OPERATED:","options":["ELECTRICALLY.","HYDRAULICALLY.","PNEUMATICALLY."],"correct":2,"expl":"Las válvulas de seguridad son de operación neumática, no eléctrica ni hidráulica.","cite":"Las válvulas de seguridad de presurización operan neumáticamente.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE TEMPERATURE OF EACH AIRCRAFT ZONE IS OPTIMIZED BY MEANS OF?","options":["A HOT AIR PRESSURE REGULATING VALVE.","A ZONE CONTROL VALVE.","A TRIM AIR VALVE.","BOTH A AND B."],"correct":2,"expl":"La temperatura de cada zona se optimiza mediante su respectiva válvula de trim air.","cite":"Optimización de temperatura por zona: mediante la válvula de trim air correspondiente.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE THIRD MOTOR (MANUAL) IN THE PRESSURIZATION SYSTEM IS ACTIVATED:","options":["AUTOMATICALLY IF BOTH AUTOMATIC MOTORS FAIL.","IN SEQUENCE AFTER EACH LANDING.","WHEN THE CABIN PRESS MODE SEL SWITCH IS POSITIONED TO MAN."],"correct":2,"expl":"El tercer motor (manual) de la válvula de outflow se activa cuando el switch CABIN PRESS MODE SEL se posiciona en MAN, no automáticamente ante la falla de los dos motores automáticos ni en secuencia tras cada aterrizaje.","cite":"Activación del motor manual de outflow: al seleccionar CABIN PRESS MODE SEL en MAN.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"THE VENT FAN RUNS ANY TIME THERE IS A NORMAL SHIPS POWER AND THE ISOLATION VALVES ARE OPEN.","options":["TRUE.","FALSE."],"correct":0,"expl":"Verdadero: el ventilador correspondiente funciona siempre que haya energía normal del avión disponible y las válvulas de aislamiento estén abiertas.","cite":"El vent fan opera con energía normal disponible y válvulas de aislamiento abiertas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"TO ENABLE RAM AIR TO THE MIXTER UNIT, THE RAM AIR SWITCH SHOULD BE USED:","options":["AT ANY TIME.","ONLY WHEN DIFFERENTIAL PRESSURE IS LESS THAN 1 PSI.","WHEN PRESSURE IS GREATER THAN 1 PSI DIFF.","ONLY AFTER OUTFLOW VALVE IS FULLY OPENED."],"correct":1,"expl":"El switch de ram air hacia la mixing unit solo debe usarse cuando la diferencial de presión de cabina es menor a 1 PSI.","cite":"Habilitación de ram air hacia la mixing unit: solo con diferencial de presión menor a 1 PSI.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"TRANSFER BETWEEN THE TWO CABIN PRESSURE CONTROLLERS IS:","options":["ACCOMPLISHED WITH A SWITCH OVERHEAD.","AUTOMATIC AFTER LANDING OR IN CASE THE OPERATING CONTROLLER FAILS.","AUTOMATICALLY AT EACH TAKEOFF."],"correct":1,"expl":"La transferencia entre ambos controladores de presurización es automática, ya sea después del aterrizaje o ante la falla del controlador que esté operando, no mediante un switch manual dedicado ni en cada despegue.","cite":"Transferencia automática de controladores de presurización: tras el aterrizaje o ante falla del controlador activo.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"TRIM AIR VALVE, EACH ONE OPTIMIZES THE TEMPERATURE BY:","options":["ADDING HOT AIR.","ADDING FRESH AIR.","MODULATION OF PACK FLOW.","ADDING RECIRCULATED AIR."],"correct":0,"expl":"Cada válvula de trim air optimiza la temperatura de su zona agregando aire caliente al flujo, no agregando aire fresco, modulando el flujo del pack, ni agregando aire recirculado.","cite":"Cada válvula de trim air optimiza la temperatura agregando aire caliente.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"TRIM AIR VALVES ARE MODULATED BY:","options":["THE ZONE CONTROLLER.","ANTI-ICE VALVE.","HOT AIR PRESSURE REGULATING VALVE."],"correct":0,"expl":"Las válvulas de trim air son moduladas por el Zone Controller, no por la válvula de anti-hielo ni por la válvula reguladora de presión de hot air directamente.","cite":"Modulación de las válvulas de trim air: a cargo del Zone Controller.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"UNDER WHAT CONDITIONS SHOULD THE PACK FLOW CONTROLLER BE SET TO HIGH?","options":["IN COLD CONDITIONS TO ACHIEVE A HIGHER CABIN TEMPERATURE RANGE.","WITH A LOW PASSENGER LOAD TO INCREASE CABIN AIR FLOW.","WITH A HIGH PASSENGER LOAD IN HOT CONDITIONS IN ORDER TO HELP REDUCE THE CABIN TEMPERATURE."],"correct":2,"expl":"Conviene seleccionar HIGH con alta carga de pasajeros en condiciones calurosas, para ayudar a reducir la temperatura de cabina ante esa mayor demanda térmica.","cite":"Selección de pack flow en HIGH: alta carga de pasajeros en condiciones calurosas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"UNDER WHAT CONDITIONS SHOULD THE PACK FLOW CONTROLLER BE SET TO LOW?","options":["WITH A LOW PASSENGER LOAD TO REDUCE BLEED AIR DEMAND AND IMPROVE FUEL EFFICIENCY.","WITH A HIGH PASSENGER LOAD TO REDUCE CABIN TEMPERATURE.","IN COLD CONDITIONS TO ACHIEVE A HIGHER CABIN TEMPERATURE RANGE.","WITH A LOW PASSENGER LOAD TO INCREASE CABIN TEMPERATURE."],"correct":0,"expl":"Conviene seleccionar LOW con baja carga de pasajeros, reduciendo la demanda de bleed air y mejorando la eficiencia de combustible.","cite":"Selección de pack flow en LOW: baja carga de pasajeros, para reducir demanda de bleed y mejorar eficiencia.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT ARE THE DIFFERENT SOURCES OF AIR FOR AIR CONDITIONING AND PRESSURIZATION?","options":["ENGINE BLEED AIR.","ENGINE BLEED AIR AND RECIRCULATED AIR.","ENGINE BLEED AIR AND RECIRCULATED AIR, OR IF SELECTED, APU BLEED AIR AND RECIRCULATED AIR.","NONE OF THE ABOVE."],"correct":2,"expl":"Las fuentes de aire para climatización y presurización son el bleed de motor combinado con aire recirculado, o si se selecciona, el bleed del APU combinado con aire recirculado.","cite":"Fuentes de aire para climatización: bleed de motor o de APU, siempre combinado con aire recirculado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT HAPPENS TO THE OUTFLOW VALVE WHEN THE RAM AIR SWITCH IS SELECTED ON?","options":["THE OUTFLOW VALVE OPENS IMMEDIATELY.","THE OUTFLOW VALVE OPENS IF CABIN DIFFERENTIAL PRESSURE IS LESS THAN 1 PSI.","NORMAL OUTFLOW VALVE CONTROL IS MAINTAINED."],"correct":1,"expl":"Al seleccionar ram air ON, la válvula de outflow abre solo si la diferencial de presión de cabina es menor a 1 PSI, respetando la misma condición de seguridad que aplica al switch de ram air.","cite":"Con ram air seleccionado ON, la válvula de outflow abre condicionada a diferencial de presión menor a 1 PSI.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT HAPPENS TO THE PACK FLOW CONTROL VALVES DURING ENGINE START?","options":["THEY MUST BE SELECTED OFF.","THEY MUST BE SELECTED OFF ON COLD DAYS ONLY.","THEY MUST BE SELECTED OFF ON HOT DAYS ONLY.","THEY AUTOMATICALLY CLOSE."],"correct":3,"expl":"Las válvulas de flujo de pack se cierran automáticamente durante el arranque de motor, sin requerir selección manual de la tripulación, para preservar presión disponible para el arranque.","cite":"Las válvulas de flujo de pack se cierran automáticamente durante el arranque de motor.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT HAPPENS WHEN A TEMPERATURE SELECTOR ROTARY KNOB IS ADJUSTED?","options":["A SIGNAL IS SENT TO THE ZONE CONTROLLER REQUESTING A DIFFERENT TEMPERATURE.","NOTHING AS THERE IS NO RELATIONSHIP BETWEEN A TEMPERATURE SELECTOR KNOB AND THE TRIM AIR VALVE.","THE ASSOCIATED TRIM AIR VALVE IMMEDIATELY MOVES TO A DIFFERENT POSITION."],"correct":0,"expl":"Al ajustar el selector de temperatura, se envía una señal al Zone Controller solicitando la nueva temperatura, que es quien luego comanda la válvula de trim air correspondiente.","cite":"Ajustar el selector de temperatura envía una señal al Zone Controller.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT IS THE FUNCTION OF THE PACK FLOW SELECTOR?","options":["ALLOWS THE PILOT TO INCREASE PACK FLOW BUT WILL NOT ALLOW A MANUAL DECREASE IN FLOW IF NEEDED BY THE AIRCRAFT DEMANDS.","ALWAYS ALLOWS HIGH FLOW REGARDLESS OF SWITCH POSITION WHEN THE APU IS USED FOR AIR CONDITIONING.","BOTH ARE CORRECT."],"correct":2,"expl":"El selector de flujo de pack permite al piloto aumentar el flujo, pero no reducirlo manualmente por debajo de lo que exige la demanda del avión, y siempre habilita flujo alto cuando el APU está siendo usado para climatización, sin importar la posición del switch.","cite":"El selector de flujo de pack permite aumentar flujo (no reducirlo bajo la demanda) y siempre da flujo alto con el APU en climatización.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT IS THE FUNCTION OF THE RAM AIR VALVE?","options":["VENTILATION WHILE ON THE GROUND.","EMERGENCY SMOKE REMOVAL AND VENTILATION IN THE EVENT LF DUAL PACK FAILURE.","AVIONICS COOLING.","CARGO VENTILATION & AVIONICS COOLING."],"correct":1,"expl":"La función principal de la válvula de ram air es la remoción de humo de emergencia y la ventilación ante una falla de ambos packs, no la ventilación general en tierra ni el enfriamiento de aviónica.","cite":"Función de la válvula de ram air: remoción de humo y ventilación de emergencia ante falla de ambos packs.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT IS THE MAXIMUM ALTITUDE ASSOCIATED WITH THE PRESSURIZATION SYSTEM?","options":["39.100 FEET.","39.800 FEET.","41.000 FEET.","41.100 FEET."],"correct":0,"expl":"La altitud máxima asociada al sistema de presurización del A320 es 39,100 ft.","cite":"Altitud máxima del sistema de presurización A320: 39,100 ft.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT IS THE MAX. NEGATIVE DIFF. PRESSURE FOR THE CABIN?","options":["0 PSI.","1 PSI.","2 PSI.","8.6 PSI."],"correct":1,"expl":"La diferencial de presión negativa máxima de cabina es 1 PSI, el mismo valor que condiciona el uso seguro del ram air.","cite":"Diferencial de presión negativa máxima de cabina: 1 PSI.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT IS THE NORM. MAX. CABIN ALTITUDE?","options":["8,000 FT.","9,550 FT +/-350 FT.","14,000 FT.","800 FT."],"correct":0,"expl":"La altitud máxima normal de cabina es 8,000 ft, el objetivo de diseño del sistema de presurización durante el crucero.","cite":"Altitud máxima normal de cabina: 8,000 ft.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT LIMITATION IS ASSOCIATED WITH THE RAM AIR VALVE?","options":["DO NOT OPEN IF CABIN PRESSURE IS GREATER THAN 1 PSI.","ONLY OPEN WHILE ON THE GROUND.","WILL NOT OPEN IF THE DITCHING SWITCH IS OFF.","OPERATION IS AUTOMATIC."],"correct":0,"expl":"No debe abrirse la válvula de ram air si la presión de cabina es mayor a 1 PSI, la misma limitación de seguridad aplicable al switch correspondiente.","cite":"Limitación de la válvula de ram air: no abrir con presión de cabina mayor a 1 PSI.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHAT POSITION DO THE PACK VALVES GO TO IN THE EVENT OF A LOSS OF THE BLEED SYSTEM PRESSURE?","options":["THEY REMAIN IN THEIR LAST POSITION.","FULL OPEN.","MID POSITION.","CLOSED."],"correct":3,"expl":"Ante la pérdida de presión del sistema de bleed, las válvulas de pack se cierran, una respuesta de protección fail-safe consistente con la lógica del resto del sistema neumático.","cite":"Ante pérdida de presión de bleed, las válvulas de pack se cierran.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN ADDITIONA PNEUMATIC AIR IS REQUIRED FOR ANTI-ICE, ENGINE STARTING, OR AIR CONDITIONING:","options":["THE CREW MUST ADJUST A MINIMUN EPR SETTING.","ADITIONAL PNEUMATIC AIR WILL BE REQUESTED BY THE BMC TO THE FADEC´S OR THE APU.","BOTH A AND B ARE CORRECT.","NONE OF THE ABOVE."],"correct":1,"expl":"El BMC es quien solicita aire neumático adicional al FADEC o al APU según corresponda, sin que la tripulación deba ajustar manualmente un EPR mínimo.","cite":"Solicitud de aire neumático adicional: gestionada automáticamente por el BMC hacia el FADEC o el APU.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN APU IS SUPPLYING THE PACKS, THE PACK CONTROLLER SENDS A DEMAND SIGNAL TO INCREASE AIRFLOW WHEN A ZONE TEMPERATURE CANNOT BE SATISFIED. THIS SIGNAL IS SENT TO THE:","options":["PACK RAM AIR INLET FLAP.","APU ECB.","PACK OUTFLOW CONTROL VALVE."],"correct":1,"expl":"Cuando el APU alimenta los packs, la señal de demanda de mayor flujo se dirige al ECB del APU, no a la compuerta de ram air del pack ni directamente a la válvula de control de outflow.","cite":"Con el APU alimentando los packs, la señal de demanda de mayor flujo se envía al ECB del APU.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN DOES NORMAL DEPRESSURIZATION OCCUR?","options":["100 FEET AGL ABOVE TOUCHDOWN.","IT IS COMPLETE THREE MINUTES AFTER TOUCHDOWN.","AFTER FLAP RETRACTION.","ON LANDING TOUCHDOWN."],"correct":1,"expl":"La despresurización normal se completa tres minutos después del touchdown, no instantáneamente al tocar tierra ni ligada a la retracción de flaps.","cite":"La despresurización normal se completa tres minutos después del touchdown.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN DOES NORMAL PRESSURIZATION OCCUR?","options":["AFTER SECOND ENGINE START.","PRESSURIZATION OCCURS DURING TAXI.","PRESSURIZATION OCCURS DURING THE TAKEOFF ROLL.","AFTER RATATION."],"correct":2,"expl":"La presurización normal ocurre durante la carrera de despegue, coincidiendo con el cierre progresivo de la válvula de outflow que estaba abierta en tierra.","cite":"La presurización normal comienza durante la carrera de despegue.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN EITHER THE BLOWER OR EXTRACT SWITCHES ARE IN OVRD, AIR FROM THE AIR CONDITIONING SYSTEM IS ADDED TO VENTILATION AIR.","options":["TRUE.","FALSE."],"correct":0,"expl":"Verdadero: al usar el override de cualquiera de los dos ventiladores, se agrega aire del sistema de aire acondicionado al flujo de ventilación de aviónica.","cite":"Con el override de blower o extract activo, se suma aire acondicionado al flujo de ventilación.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN LANDING ELEVATION IS SET TO AUTO, THE LANDING ELEVATION IS SENT TO THE CONTROLLER FROM:","options":["FMGS.","FCU.","ADIRS."],"correct":0,"expl":"En modo AUTO, la elevación de aterrizaje proviene del FMGS (basada en el plan de vuelo), no del FCU ni directamente del ADIRS.","cite":"Elevación de aterrizaje en modo AUTO: proporcionada por el FMGS.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN THE PACK FLOW CONTROL KNOB IS POSITIONED TO HI, AIR FLOW IS:","options":["80% OF NORMAL RATE.","100% OF NORMAL RATE.","120% OF NORMAL RATE.","150% OF NORMAL RATE."],"correct":2,"expl":"En posición HI, el flujo de aire del pack corresponde al 120% de la tasa normal.","cite":"Flujo de pack en posición HI: 120% de la tasa normal.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN WOULD YOU SELECT PACK FLOW TO HI?","options":["SMOKE REMOVAL OR HOT/HUMID CONDITIONS.","WHEN PASSENGERS ARE COMPLAINING IT IS TOO COLD.","ABOVE FL 350.","ABOVE FL 250."],"correct":0,"expl":"Conviene seleccionar HI para remoción de humo o en condiciones calurosas/húmedas, no simplemente porque los pasajeros se quejen de frío ni por criterios de altitud de vuelo.","cite":"Selección de pack flow HI: remoción de humo o condiciones calurosas/húmedas.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHEN WOULD YOU SELECT RAM AIR ON?","options":["IF ADDITIONAL COOLING IS REQUIRED ON THE GROUND.","DUAL PACKS FAILURE OR SMOKE REMOVAL.","WHEN PACK TEMPERATURES ARE TOO HIGH.","WHEN THERE IS SMOKE IN THE CABIN."],"correct":1,"expl":"Se selecciona ram air ON ante una falla de ambos packs o para remoción de humo, no simplemente para enfriamiento adicional en tierra ni cuando la temperatura de los packs es alta.","cite":"Selección de ram air ON: falla de ambos packs o remoción de humo.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHICH CONFIGURATION IS THE AVIONICS VENTILATION SYSTEM IN WHILE AIRBORNE WITH NO ABNORMALS PRESENT?","options":["OPEN.","SMOKE.","FIRE.","CLOSED."],"correct":3,"expl":"En vuelo, sin condiciones anormales, el sistema de ventilación de aviónica opera en configuración cerrada (circuito cerrado con intercambiador de calor).","cite":"Configuración normal en vuelo del sistema de ventilación de aviónica: cerrada.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHICH OF THE FOLLOWING STATEMENTS IS CORRECT CONCERNING CONDITIONED AIR?","options":["CONDITIONED AIR AND TRIM AIR ARE MIXED THEN DISTRIBUTED TO EACH ZONE.","RECIRCULATED AIR, CONDITIONED AND HOT TRIM ARE MIXED THEN DISTRIBUTED TO EACH ZONE.","HOT TRIM AIR IS ADDED TO THE MIXING UNIT BEFORE DISTRIBUCION TO EACH ZONE.","RECIRCULING FANS DRAW CABIN AIR TO A MIXING UNIT WHERE CONDITIONED AIR IS ADDED."],"correct":3,"expl":"Los ventiladores de recirculación llevan aire de cabina hacia la mixing unit, donde se le agrega aire condicionado proveniente de los packs, formando la mezcla que luego se distribuye.","cite":"El aire de recirculación se combina con aire condicionado en la mixing unit.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHICH STATEMENT IS CORRECT REGARDING ILLUMINATION OF THE AMBER AFT ISOL VALVE FAULT LIGHT?","options":["AUTOMATICALLY CLOSES THE AFT CARGO COMPARTMENT ISOLATION VALVES.","MEANS THAT EITHER THE INLET OR OUTLET ISOLATION VALVE(S) DISAGREES WITH THE SWITCH POSITION.","INDICATES THAT THE EXTRACT FAN HAS STOPPED.","ALL OF THE ABOVE."],"correct":1,"expl":"Esta luz FAULT significa que la válvula de aislamiento (de entrada o de salida) no coincide con la posición comandada por el switch, no que se cierre automáticamente ni que indique directamente una falla del extractor.","cite":"FAULT de la válvula de aislamiento AFT: discrepancia de posición respecto del switch comandado.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WHICH STATEMENT IS TRUE CONCERNING THE CARGO COMPARTMENT VENTILATION?","options":["BOTH CARGO COMPARTMENTS ARE PRESSURIZED AND HEATED USING BOTH CABIN AIR AND HOT TRIM AIR.","RECIRCULATED AIR, CONDITIONED AIR, AND HOT TRIM AIR ARE MIXED THEN DISTRIBUTED TO EACH CARGO COMPARTMENT.","ONLY THE AFT CARGO COMPARTMENT IS HEATED AND VENTILATED. CABIN AMBIENT AIR IS MIXED WITH HOT TRIM AIR AND DRAWN THROUGH ISOLATION VALVES BY EXTRACTION FANS."],"correct":2,"expl":"Solo la bodega de carga trasera cuenta con calefacción y ventilación activa: aire ambiente de cabina se mezcla con aire caliente de trim y se extrae a través de válvulas de aislamiento mediante ventiladores de extracción; la bodega delantera no tiene este mismo tratamiento.","cite":"Únicamente la bodega de carga trasera está calefaccionada y ventilada activamente, no la delantera.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WITH THE APU RUNNING, THE APU BLEED PUSH BUTTON SELECTED ON AND THE X BLEED SELECTOR TO AUTO, THE APU WILL:","options":["ONLY SUPPLY BLEED AIT TO LEFT SIDE.","SUPPLY PENEUMATIC AIR TO BOTH SIDES OF THE AIRCRAFT BECAUSE THE PNEUMATIC CROSSBLED VALVE AUTOMATICALLY OPENS.","WILL SUPPLY BLEED AIR ONLY TO THE LEFT SIDE UNLESS THE X BLEED SELECTOR IS SELECTED OPEN.","ONLY SUPPLY BLEED AIR TO THE RIGHT SIDE."],"correct":1,"expl":"Con el APU funcionando, su bleed seleccionado ON, y el selector de crossbleed en AUTO, el APU suministra aire neumático a ambos lados del avión porque la válvula de crossbleed abre automáticamente en esa condición.","cite":"Con bleed del APU ON y crossbleed en AUTO, el APU alimenta ambos lados del avión automáticamente.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WITH APU BLEED ON AND ENGINE BLEED SWITCHES ON WITH ENGINES RUNNING. WHAT IS THE POSITION OF THE ENGINE BLEED VALVES?","options":["CLOSED.","OPEN.","DEPENDS ON THE CROSSBLEED SELECTOR."],"correct":0,"expl":"Con el bleed del APU activo (que tiene prioridad), las válvulas de bleed de motor permanecen cerradas aunque sus switches estén en ON y los motores en marcha.","cite":"Con bleed del APU activo, las válvulas de bleed de motor permanecen cerradas por la prioridad del APU.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WITH THE LOSS OF PNEUMATIC SYSTEM PRESSURE, THE ENGINE BLEED VALVE WILL:","options":["REMAIN IN IT'S CURRENT POSITION.","ASSUME THE CLOSED POSITION.","ASSUME THE OPEN POSITION.","ASSUME THE MID POSITION."],"correct":1,"expl":"Ante la pérdida de presión del sistema neumático, la válvula de bleed de motor asume la posición cerrada, la misma lógica fail-safe aplicada a las válvulas de pack.","cite":"Ante pérdida de presión neumática, la válvula de bleed de motor cierra.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true},
{"q":"WITH THE PRESSURIZATION SYSTEM IN THE AUTOMATIC MODE, WHICH VALVES ARE CLOSED WHEN THE DITCHING PUSH BUTTON IS SELECTED ON?","options":["ALL VALVES BELOW THE WATER LINE.","APU INLET.","ONLY THE AVONICS COOLING VALVES.","THE ENGINE BLEED VALVES."],"correct":0,"expl":"Al seleccionar DITCHING, se cierran todas las válvulas ubicadas por debajo de la línea de flotación, no solo la entrada del APU, las válvulas de enfriamiento de aviónica, o las de bleed de motor de forma aislada.","cite":"DITCHING ON: cierre de todas las válvulas ubicadas por debajo de la línea de flotación.","src":"Examen oficial DGAC A320 (2018) — respuesta verificada","bank":"dgac","bank_section":"Air conditioning and pneumatic","editorial_audit":"2026-09-08","historical_text_cleanup":true}
];
